// Generated by scripts/generate-articles.ts. Do not edit.
export default {"html":"<h2 id=\"overview\" data-line=\"0\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#overview\" aria-hidden=\"true\"></a> Overview</h2>\n<p data-line=\"1\" class=\"code-line\">I released <code>@rdlabo/eslint-plugin-rules</code> 🎉<br>\nI build apps with Ionic and Angular, and I packaged the ESLint rules I needed along the way into a plugin. Some of the features honestly made my work dramatically more efficient. On a large application, migration work that would normally take two or three days finished in an instant. Hooray!</p>\n<h2 id=\"usage\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#usage\" aria-hidden=\"true\"></a> Usage</h2>\n<ul data-line=\"6\" class=\"code-line\">\n<li data-line=\"6\" class=\"code-line\">Assumes <code>@angular/core &gt;= 15</code>. It should work on 14, but not on 13.</li>\n<li data-line=\"7\" class=\"code-line\">You need the <code>@angular-eslint</code> packages applied to your project. If you have not done that yet, install them using <a href=\"https://github.com/angular-eslint/angular-eslint\" target=\"_blank\" rel=\"noopener noreferrer\">this guide</a>.</li>\n<li data-line=\"8\" class=\"code-line\">If you use <code>prettier</code>, keep it up to date. An old <code>prettier</code> version throws an error when you <code>inject</code> an object with a generic type parameter.</li>\n</ul>\n<h2 id=\"installation\" data-line=\"10\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#installation\" aria-hidden=\"true\"></a> Installation</h2>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"12\"><span class=\"line\"><span style=\"color:#B392F0\">%</span><span style=\"color:#9ECBFF\"> npm</span><span style=\"color:#9ECBFF\"> install</span><span style=\"color:#9ECBFF\"> @rdlabo/eslint-plugin-rules</span><span style=\"color:#79B8FF\"> --save-dev</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"configuration\" data-line=\"16\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#configuration\" aria-hidden=\"true\"></a> Configuration</h2>\n<p data-line=\"18\" class=\"code-line\">Configure <code>.eslintrc*</code> as follows. This shows my recommended setup, but of course you can skip any rules you do not want.</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">json</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"20\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span> {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   ...</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   \"plugins\": [\"@rdlabo/rules\"],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   \"overrides\": [</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       \"files\": [</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>         \"*.ts\"</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       ],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     ...</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       \"rules\": {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>         \"@rdlabo/rules/deny-constructor-di\": \"error\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>         \"@rdlabo/rules/import-inject-object\": \"error\",</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     },</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       \"files\": [</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>         \"*.html\"</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       ],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       \"rules\": {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>         \"@rdlabo/rules/deny-element\": [</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>           \"error\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>           {</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>             \"elements\": [</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-modal\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-popover\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-toast\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-alert\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-loading\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-picker\",</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>               \"ion-action-sheet\"</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>             ]</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>           }</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>         ]</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>         ]</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>       }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     }</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   ]</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span> }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><h2 id=\"rule-reference\" data-line=\"61\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#rule-reference\" aria-hidden=\"true\"></a> Rule reference</h2>\n<h3 id=\"%40rdlabo%2Frules%2Fdeny-constructor-di\" data-line=\"63\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#%40rdlabo%2Frules%2Fdeny-constructor-di\" aria-hidden=\"true\"></a> @rdlabo/rules/deny-constructor-di</h3>\n<p data-line=\"64\" class=\"code-line\">This rule helps you migrate to the <code>inject</code> function introduced in Angular 14. Use it when moving away from DI in <code>constructor</code>. Both styles work today, but after reading the article below you will want to migrate!</p>\n<p data-line=\"66\" class=\"code-line\"><a href=\"https://zenn.dev/lacolaco/articles/why-inject-function-wins\" rel=\"noopener noreferrer\" target=\"_blank\">https://zenn.dev/lacolaco/articles/why-inject-function-wins</a><a href=\"https://zenn.dev/lacolaco/articles/why-inject-function-wins\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://zenn.dev/lacolaco/articles/why-inject-function-wins</a></p>\n<p data-line=\"68\" class=\"code-line\">Before migration: DI in <code>constructor</code> triggers an error.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"70\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-confirm'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./confirm.page.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./confirm.page.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> SigninPage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">public</span><span style=\"color:#FFAB70\"> platform</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Platform</span><span style=\"color:#E1E4E8\">) {} </span><span style=\"color:#a0aab5\">// Error: Do not use constructor DI.</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"81\" class=\"code-line\">After migration: use the <code>inject</code> function.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"83\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  selector: </span><span style=\"color:#9ECBFF\">'app-confirm'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  templateUrl: </span><span style=\"color:#9ECBFF\">'./confirm.page.html'</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  styleUrls: [</span><span style=\"color:#9ECBFF\">'./confirm.page.scss'</span><span style=\"color:#E1E4E8\">],</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> SigninPage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  public</span><span style=\"color:#F97583\"> readonly</span><span style=\"color:#FFAB70\"> platform</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(Platform); </span><span style=\"color:#a0aab5\">// OK</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {}</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"96\" class=\"code-line\">This rule supports auto-fix, so <code>npm run lint -- --fix</code> completes the migration automatically. For the example above, it generates a diff like this.</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"98\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span>   @Component({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     selector: 'app-confirm',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     templateUrl: './confirm.page.html',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     styleUrls: ['./confirm.page.scss'],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   export class SigninPage {</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>     constructor(public platform: Platform) {}</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     public readonly platform = inject(Platform); // OK</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span></span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     constructor() {}</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"112\"><span class=\"line\"><span class=\"diff-prefix\"> </span><span>   @Component({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     selector: 'app-confirm',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     templateUrl: './confirm.page.html',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     styleUrls: ['./confirm.page.scss'],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   export class SigninPage {</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>     constructor(</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>       public platform: Platform,</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>       private store: Store&lt;IApp&gt;,</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>       private navCtrl: NavController,</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>       public helper: HelperService,</span></span>\n<span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>     ) {}      </span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     public readonly platform = inject(Platform);</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     private readonly store = inject(Store&lt;IApp&gt;);</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     private readonly navCtrl = inject(NavController);</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     public readonly helper = inject(HelperService);</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     </span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>     constructor() {}</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><p data-line=\"134\" class=\"code-line\">On a large project that means more than 100 files and thousands of DI sites—fixing that by hand is not realistic. You could die trying. Let automation do the work!</p>\n<h3 id=\"%40rdlabo%2Frules%2Fimport-inject-object\" data-line=\"136\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#%40rdlabo%2Frules%2Fimport-inject-object\" aria-hidden=\"true\"></a> @rdlabo/rules/import-inject-object</h3>\n<p data-line=\"138\" class=\"code-line\">If you use the <code>inject</code> function without importing it, you get an error. I split this out because generating the <code>inject</code> import in the auto-fix for <code>@rdlabo/rules/deny-constructor-di</code> was hard. <code>npm run lint -- --fix</code> adds the import automatically.</p>\n<div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"140\"><span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   import { inject } from '@angular/core';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   @Component({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     selector: 'app-confirm',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     templateUrl: './confirm.page.html',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     styleUrls: ['./confirm.page.scss'],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   export class SigninPage {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     public readonly platform = inject(Platform);</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><div class=\"code-block-container\"><div class=\"code-block-filename-container\"><span class=\"code-block-filename\">ts</span></div><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"153\"><span class=\"line diff remove\"><span class=\"diff-prefix\">-</span><span>   import { Component } from '@angular/core';</span></span>\n<span class=\"line diff add\"><span class=\"diff-prefix\">+</span><span>   import { Component, inject } from '@angular/core';</span></span>\n<span class=\"line\"><span></span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   @Component({</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     selector: 'app-confirm',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     templateUrl: './confirm.page.html',</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     styleUrls: ['./confirm.page.scss'],</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   })</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   export class SigninPage {</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>     public readonly platform = inject(Platform);</span></span>\n<span class=\"line\"><span class=\"diff-prefix\"> </span><span>   }</span></span>\n<span class=\"line\"><span></span></span></code></pre></div><h3 id=\"%40rdlabo%2Frules%2Fdeny-element\" data-line=\"167\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#%40rdlabo%2Frules%2Fdeny-element\" aria-hidden=\"true\"></a> @rdlabo/rules/deny-element</h3>\n<p data-line=\"169\" class=\"code-line\">Since Ionic 6, inline Modals and ActionSheets are supported. On projects I work on, we standardize on creating them through Controllers, so I added this rule to avoid accidentally creating them inline. You can also use it to ban other specific HTML elements.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"171\"><span class=\"line\"><span style=\"color:#E1E4E8\">{</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">  \"rules\"</span><span style=\"color:#E1E4E8\">: {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    \"@rdlabo/rules/deny-element\"</span><span style=\"color:#E1E4E8\">: [</span></span>\n<span class=\"line\"><span style=\"color:#9ECBFF\">      \"error\"</span><span style=\"color:#E1E4E8\">,</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        \"elements\"</span><span style=\"color:#E1E4E8\">: [</span><span style=\"color:#9ECBFF\">\"ion-modal\"</span><span style=\"color:#E1E4E8\">]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    ]</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"184\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">ion-modal</span><span style=\"color:#E1E4E8\">&gt;&lt;/</span><span style=\"color:#85E89D\">ion-modal</span><span style=\"color:#E1E4E8\">&gt;</span><span style=\"color:#a0aab5\">&lt;!-- This causes an error --&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"summary\" data-line=\"188\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"189\" class=\"code-line\">In day-to-day development, \"try hard\" and \"be careful\" inevitably wear you down. Turning expectations into rules and automating them reduces the burden on developers. Please give it a try. And if it saves you real time, buy me a drink sometime (lol)</p>\n","headings":[{"id":"overview","text":"Overview","level":2},{"id":"usage","text":"Usage","level":2},{"id":"installation","text":"Installation","level":2},{"id":"configuration","text":"Configuration","level":2},{"id":"rule-reference","text":"Rule reference","level":2},{"id":"%40rdlabo%2Frules%2Fdeny-constructor-di","text":"@rdlabo/rules/deny-constructor-di","level":3},{"id":"%40rdlabo%2Frules%2Fimport-inject-object","text":"@rdlabo/rules/import-inject-object","level":3},{"id":"%40rdlabo%2Frules%2Fdeny-element","text":"@rdlabo/rules/deny-element","level":3},{"id":"summary","text":"Summary","level":2}]} as const;
